 const pin=document.createElement('button');pin.className='room-pin';pin.textContent=room.name;pin.setAttribute('aria-label',`Toggle ${room.name.toLowerCase()} lights in model`);pin.setAttribute('aria-pressed','false');pin.dataset.room=room.id;labels.append(pin);
