const orbit=new OrbitControls(camera,renderer.domElement);orbit.target.set(-.1,3.1,0);orbit.enableDamping=true;orbit.dampingFactor=.08;orbit.enablePan=false;orbit.minPolarAngle=.55;orbit.maxPolarAngle=1.47;orbit.minAzimuthAngle=-1.05;orbit.maxAzimuthAngle=1.05;orbit.minZoom=.65;orbit.maxZoom=2.5;orbit.rotateSpeed=.65;orbit.zoomSpeed=.7;
const moon=new THREE.DirectionalLight('#97b9e3',1.15);moon.position.set(-3,11,8);moon.castShadow=true;moon.shadow.mapSize.set(2048,2048);moon.shadow.camera.left=-12;moon.shadow.camera.right=12;moon.shadow.camera.top=10;moon.shadow.camera.bottom=-10;moon.shadow.normalBias=.035;moon.shadow.bias=-.0004;scene.add(moon);
