// Soft contact shadow gives the little model a grounded, floating-plinth feel.
const shadowCanvas=document.createElement('canvas');shadowCanvas.width=128;shadowCanvas.height=128;const shadowCtx=shadowCanvas.getContext('2d');const grad=shadowCtx.createRadialGradient(64,64,4,64,64,64);grad.addColorStop(0,'rgba(0,0,0,.65)');grad.addColorStop(.6,'rgba(0,0,0,.3)');grad.addColorStop(1,'rgba(0,0,0,0)');shadowCtx.fillStyle=grad;shadowCtx.fillRect(0,0,128,128);
const shadow=new THREE.Mesh(new THREE.PlaneGeometry(18,10),new THREE.MeshBasicMaterial({map:new THREE.CanvasTexture(shadowCanvas),transparent:true,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.set(-1.5,-.27,0);scene.add(shadow);
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();const activePointers=new Set();let view='all',hovered=null,downPointer=null,dragged=false,needsRender=true,firstRender=true;
const roomButtons=[...document.querySelectorAll('[data-room]')];
function announce(message){document.querySelector('#announcement').textContent=message;}
function updateUI(){let count=0;for(const room of Object.values(home.rooms)){if(room.on)count++;for(const button of roomButtons.filter(b=>b.dataset.room===room.id))button.setAttribute(button.role==='switch'?'aria-checked':'aria-pressed',String(room.on));}document.querySelector('#count').textContent=`${count} / ${ROOMS.length} on`;document.querySelector('#all-on').disabled=count===ROOMS.length;document.querySelector('#all-off').disabled=count===0;document.querySelector('#mood-message').innerHTML=count===0?"The world can wait.<br>You're home.":count===ROOMS.length?'Every corner, a little warmer.<br>Welcome home.':`${count} ${count===1?'room is':'rooms are'} glowing.<br>Make the evening yours.`;}
function setRoom(id,on){const room=home.rooms[id];if(!room||typeof on!=='boolean')throw new Error('Choose a valid room and a true or false light state.');room.on=on;needsRender=true;updateUI();announce(`${room.name} lights ${on?'on':'off'}.`);return {room:id,on};}
for(const button of roomButtons)button.addEventListener('click',()=>setRoom(button.dataset.room,!home.rooms[button.dataset.room].on));
document.querySelector('#all-on').addEventListener('click',()=>{for(const r of ROOMS)setRoom(r.id,true);announce('All seven rooms are lit.');});
document.querySelector('#all-off').addEventListener('click',()=>{for(const r of ROOMS)setRoom(r.id,false);announce('All room lights are off.');});
function visiblePicks(){return home.picks.filter(m=>m.parent.visible);}
function hitAt(event){const rect=renderer.domElement.getBoundingClientRect();pointer.x=(event.clientX-rect.left)/rect.width*2-1;pointer.y=-(event.clientY-rect.top)/rect.height*2+1;raycaster.setFromCamera(pointer,camera);return raycaster.intersectObjects(visiblePicks(),false)[0]?.object.userData.room??null;}
const tooltip=document.querySelector('#room-tooltip');
renderer.domElement.addEventListener('pointerdown',e=>{activePointers.add(e.pointerId);if(e.button!==0||activePointers.size>1){downPointer=null;dragged=true;return;}downPointer={x:e.clientX,y:e.clientY,id:e.pointerId};dragged=false;});
renderer.domElement.addEventListener('pointermove',e=>{if(downPointer&&Math.hypot(e.clientX-downPointer.x,e.clientY-downPointer.y)>5)dragged=true;const id=hitAt(e);hovered=id;renderer.domElement.style.cursor=dragged?'grabbing':id?'pointer':'grab';if(id&&!downPointer&&e.pointerType!=='touch'){const rect=host.getBoundingClientRect();tooltip.textContent=`${home.rooms[id].name} · ${home.rooms[id].on?'lights off':'lights on'}`;tooltip.style.left=`${Math.min(e.clientX-rect.left+15,rect.width-180)}px`;tooltip.style.top=`${e.clientY-rect.top-35}px`;tooltip.style.display='block';}else tooltip.style.display='none';});
renderer.domElement.addEventListener('pointerup',e=>{activePointers.delete(e.pointerId);if(downPointer&&downPointer.id===e.pointerId&&!dragged){const id=hitAt(e);if(id)setRoom(id,!home.rooms[id].on);}downPointer=null;dragged=false;});
renderer.domElement.addEventListener('pointercancel',e=>{activePointers.delete(e.pointerId);downPointer=null;dragged=false;});renderer.domElement.addEventListener('pointerleave',()=>{tooltip.style.display='none';});
window.addEventListener('pointerup',e=>{activePointers.delete(e.pointerId);downPointer=null;dragged=false;});orbit.addEventListener('change',()=>{needsRender=true;tooltip.style.display='none';});
function resize(){const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;const aspect=w/h;let size=view==='all'?5.45:view==='up'?4.8:4.3;const widthRequired=view==='down'?12.6:15.8;size=Math.max(size,widthRequired/(2*aspect));camera.left=-size*aspect;camera.right=size*aspect;camera.top=size;camera.bottom=-size;camera.updateProjectionMatrix();renderer.setSize(w,h);needsRender=true;}
new ResizeObserver(resize).observe(host);
function resetView(){camera.zoom=1;const target=view==='down'?new THREE.Vector3(-1.65,1.7,0):view==='up'?new THREE.Vector3(0,4.9,0):new THREE.Vector3(-.1,3.25,0);orbit.target.copy(target);camera.position.copy(target).add(new THREE.Vector3(-5.5,7.7,23));orbit.update();resize();}
for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>{view=b.dataset.view;home.floors.down.visible=view!=='up';home.floors.up.visible=view!=='down';shadow.visible=view!=='up';renderer.shadowMap.needsUpdate=true;for(const other of document.querySelectorAll('[data-view]')){other.classList.toggle('active',other===b);other.setAttribute('aria-pressed',String(other===b));}for(const r of ROOMS){const pin=labels.querySelector(`[data-room=${r.id}]`);pin.hidden=(view==='down'&&r.floor==='up')||(view==='up'&&r.floor==='down');}resetView();announce(`${b.textContent} view.`);});
function zoom(delta){camera.zoom=THREE.MathUtils.clamp(camera.zoom+delta,orbit.minZoom,orbit.maxZoom);camera.updateProjectionMatrix();needsRender=true;}
document.querySelector('#zoom-in').addEventListener('click',()=>zoom(.2));document.querySelector('#zoom-out').addEventListener('click',()=>zoom(-.2));document.querySelector('#reset-view').addEventListener('click',resetView);
renderer.domElement.addEventListener('keydown',e=>{if(e.key==='+'||e.key==='='){zoom(.2);e.preventDefault();}else if(e.key==='-'){zoom(-.2);e.preventDefault();}else if(e.key==='Home'){resetView();e.preventDefault();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){const offset=camera.position.clone().sub(orbit.target),s=new THREE.Spherical().setFromVector3(offset);s.theta+=e.key==='ArrowLeft'?-.12:e.key==='ArrowRight'?.12:0;s.phi+=e.key==='ArrowUp'?-.08:e.key==='ArrowDown'?.08:0;s.phi=THREE.MathUtils.clamp(s.phi,orbit.minPolarAngle,orbit.maxPolarAngle);s.theta=THREE.MathUtils.clamp(s.theta,orbit.minAzimuthAngle,orbit.maxAzimuthAngle);camera.position.copy(orbit.target).add(new THREE.Vector3().setFromSpherical(s));orbit.update();needsRender=true;e.preventDefault();}});
const dialog=document.querySelector('#reference-dialog');document.querySelector('#open-reference').addEventListener('click',()=>dialog.showModal());document.querySelector('#close-reference').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function positionLabels(){for(const r of ROOMS){const p=new THREE.Vector3(...(view==='down'&&r.id==='gallery'?[-2.3,.4,1.5]:r.pin)).project(camera);const pin=labels.querySelector(`[data-room=${r.id}]`);pin.textContent=host.clientWidth<450?({living:'Living',kitchen:'Kitchen',bedroom:'Bedroom',gallery:'Hall',shower:'Shower',bath:'Bath',study:'Study'}[r.id]):r.name;pin.style.left=`${(p.x*.5+.5)*host.clientWidth}px`;pin.style.top=`${(-p.y*.5+.5)*host.clientHeight}px`;pin.style.visibility=p.z>1||p.z< -1?'hidden':'visible';}}
let last=performance.now();
function animate(now){requestAnimationFrame(animate);if(document.hidden)return;const dt=Math.min((now-last)/1000,.1);last=now;orbit.update();let changing=false;for(const r of Object.values(home.rooms)){const target=r.on?1:0;if(Math.abs(r.fade-target)>.001){r.fade=reduced?target:THREE.MathUtils.lerp(r.fade,target,1-Math.exp(-dt*6));changing=true;}else r.fade=target;for(const {light,intensity} of r.lights)light.intensity=intensity*r.fade;for(const m of r.glows)m.emissiveIntensity=r.fade*1.8;}if(needsRender||changing){renderer.render(scene,camera);positionLabels();needsRender=false;if(firstRender){firstRender=false;document.querySelector('#loading').remove();renderer.shadowMap.autoUpdate=false;}}}
resetView();updateUI();requestAnimationFrame(animate);
